SET ROLE c4g_organization_profile_owner;
DO $$ DECLARE tab text; present boolean; BEGIN
 FOREACH tab IN ARRAY ARRAY['profile_draft','profile_draft_revision','profile_item_version','profile_revision_item','idempotency_record'] LOOP
  EXECUTE format('LOCK TABLE organization_profile.%I IN ACCESS EXCLUSIVE MODE',tab);
  -- Owner must observe all protected rows, not an empty RLS-filtered view.
  -- A refusal rolls this change back with the entire migration transaction.
  EXECUTE format('ALTER TABLE organization_profile.%I NO FORCE ROW LEVEL SECURITY',tab);
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM organization_profile.%I)',tab) INTO present;
  IF present THEN RAISE EXCEPTION 'F13_AUTHORING_008_DOWN_REFUSES_DATA_LOSS'; END IF;
 END LOOP;
END $$;
DROP TABLE organization_profile.idempotency_record,organization_profile.profile_revision_item,organization_profile.profile_item_version;
ALTER TABLE organization_profile.profile_draft DROP CONSTRAINT profile_draft_head_fk;
DROP TABLE organization_profile.profile_draft_revision,organization_profile.profile_draft;
DROP FUNCTION organization_profile.guard_authoring_head(),organization_profile.guard_authoring_draft(),organization_profile.guard_authoring_immutable(),organization_profile.guard_authoring_item(),organization_profile.guard_authoring_material();
ALTER TABLE organization_profile.profile_scope DROP CONSTRAINT profile_scope_tenant_identity;
RESET ROLE;
REVOKE SELECT,INSERT ON organization_profile.profile_scope FROM c4g_organization_profile_runtime;
REVOKE SELECT(scope_id,organization_id,scope_type,lifecycle) ON organizational_scope.scope FROM c4g_organization_profile_runtime;
REVOKE USAGE ON SCHEMA organizational_scope FROM c4g_organization_profile_runtime;
